typedef struct {
  int ax, ay, w, h;              /* artwork coordinates */
  double period, next;
  cairo_surface_t *pristine;     /* untouched artwork pixels */
  cairo_surface_t *work;         /* frame buffer, shared with ximage */
#ifndef HUD_NO_X11
  XImage *ximage;
  XShmSegmentInfo shm;
  int shared;
#endif
} HudRegion;

/* Published by xsecurelock-power on the root window (see its power_button.h):
 * the panel in root coordinates and the state of the two buttons. On the
 * wire the pressed and hovered buttons are sent + 1 (CARDINAL is unsigned);
 * here they are -1 (none), 0 (reboot) or 1 (shut down). */
typedef struct {
  long version, x, y, w, h, gap, horizontal, pressed, status[2], hover;
} HudPowerUi;

typedef struct {
  cairo_font_options_t *font_options;
  cairo_font_face_t *regular, *bold;
  cairo_surface_t *ticker;
  HudRegion region[HUD_REGIONS];
  /* Live machine activity: sampled once a second, eased every frame. */
  SysStats stats;
  int stats_live;
  double stats_next, last_t;
  /* Network history, newest first: time (ms) and bytes/s per direction. */
  double net_t[HUD_NET_HISTORY], net_rx[HUD_NET_HISTORY], net_tx[HUD_NET_HISTORY];
  int net_count;
  double net_scale;       /* eased full-scale value, bytes/s */
  double cpu, core[16], mem, swap, disk, net;  /* displayed, 0..1 */
  int subsys[4];          /* status level per subsystem row, -1 unknown */
  double therm[STATS_T_COUNT], therm_peak[STATS_T_COUNT];  /* deg C, -1 unknown */
  double bat_pct, bat_watts, flow_phase;  /* eased battery view, -1 unknown */
  HudPowerUi power;       /* reboot/shutdown panel, valid when power_on */
  int power_on, power_shown;
  long power_ox, power_oy; /* artwork origin in root coordinates */
#ifndef HUD_NO_X11
  Window power_root;
  Atom power_atom, power_shown_atom;
#endif
  double power_next;
  double hover_from[2], hover_t0[2];  /* hover fade: start value and time */
#ifndef HUD_NO_X11
  GC gc;
#endif
  int left, top, ready, ticker_period, hex_key, use_shm;
} Hud;

