static void hud_rgb(cairo_t *cr, unsigned rgb, double alpha) {
  cairo_set_source_rgba(cr, ((rgb >> 16) & 255) / 255., ((rgb >> 8) & 255) / 255.,
                        (rgb & 255) / 255., alpha);
}

/* Monospace text; `spacing` > 0 adds letter spacing like the Pango-rendered art. */
static double hud_text(cairo_t *cr, cairo_font_face_t *face, double size,
                       double x, double y, unsigned rgb, double alpha,
                       double spacing, const char *text) {
  cairo_set_font_face(cr, face);
  cairo_set_font_size(cr, size);
  hud_rgb(cr, rgb, alpha);
  if (spacing <= 0) {
    cairo_text_extents_t e;
    cairo_text_extents(cr, text, &e);
    cairo_move_to(cr, x, y);
    cairo_show_text(cr, text);
    return e.x_advance;
  }
  double start = x;
  char glyph[8];
  for (const unsigned char *p = (const unsigned char *)text; *p;) {
    int len = *p < 0x80 ? 1 : (*p >> 5) == 6 ? 2 : (*p >> 4) == 14 ? 3 : 4;
    int i = 0;
    for (; i < len && p[i]; ++i) glyph[i] = (char)p[i];
    glyph[i] = 0;
    cairo_text_extents_t e;
    cairo_text_extents(cr, glyph, &e);
    cairo_move_to(cr, x, y);
    cairo_show_text(cr, glyph);
    x += e.x_advance + spacing;
    p += i;
  }
  return x - start;
}

static cairo_t *hud_context(Hud *hud, cairo_surface_t *surface) {
  cairo_t *cr = cairo_create(surface);
  cairo_set_font_options(cr, hud->font_options);
  cairo_set_tolerance(cr, .5);  /* half-pixel curve flattening: same look, fewer edges */
  return cr;
}

#ifndef HUD_NO_X11
static void hud_region_free(Display *dpy, HudRegion *g) {
  if (g->work) cairo_surface_destroy(g->work);
  if (g->pristine) cairo_surface_destroy(g->pristine);
  if (g->ximage) {
    if (g->shared) {
      XShmDetach(dpy, &g->shm);
      XSync(dpy, False);
      shmdt(g->shm.shmaddr);
      g->ximage->data = NULL;
    }
    XDestroyImage(g->ximage);  /* frees malloc'd data in the plain case */
  }
  memset(g, 0, sizeof(*g));
}
#endif

#ifndef HUD_NO_X11
/* Frees the drawing resources (lock screen and tests). */
static void hud_assets_free(Hud *hud) {
  if (hud->ticker) cairo_surface_destroy(hud->ticker);
  if (hud->font_options) cairo_font_options_destroy(hud->font_options);
  if (hud->regular) cairo_font_face_destroy(hud->regular);
  if (hud->bold) cairo_font_face_destroy(hud->bold);
  hud->ticker = NULL;
  hud->font_options = NULL;
  hud->regular = hud->bold = NULL;
}
#endif

#ifndef HUD_NO_X11
static void hud_destroy(Display *dpy, Hud *hud) {
  for (int i = 0; i < HUD_REGIONS; ++i) hud_region_free(dpy, &hud->region[i]);
  if (hud->gc) XFreeGC(dpy, hud->gc);
  hud_assets_free(hud);
  memset(hud, 0, sizeof(*hud));
}

/* One region: shared-memory XImage if possible, otherwise a plain one. Its
 * pixels double as a Cairo RGB24 surface (the artwork format checked by
 * load_image: 32 bpp, LSB first, 0xff0000/0xff00/0xff masks). */
static int hud_region_init(Display *dpy, XWindowAttributes *attr, XImage *art,
                           Hud *hud, HudRegion *g) {
  int stride = cairo_format_stride_for_width(CAIRO_FORMAT_RGB24, g->w);
  if (hud->use_shm) {
    g->ximage = XShmCreateImage(dpy, attr->visual, (unsigned)attr->depth, ZPixmap,
                                NULL, &g->shm, (unsigned)g->w, (unsigned)g->h);
    if (g->ximage && g->ximage->bytes_per_line == stride) {
      g->shm.shmid = shmget(IPC_PRIVATE, (size_t)stride * g->h, IPC_CREAT | 0600);
      if (g->shm.shmid >= 0) {
        g->shm.shmaddr = g->ximage->data = shmat(g->shm.shmid, NULL, 0);
        g->shm.readOnly = True;
        if (g->shm.shmaddr != (char *)-1 && XShmAttach(dpy, &g->shm)) {
          XSync(dpy, False);
          g->shared = 1;
        }
        /* Removed now; it disappears once the server and we detach. */
        shmctl(g->shm.shmid, IPC_RMID, NULL);
        if (!g->shared && g->shm.shmaddr != (char *)-1) shmdt(g->shm.shmaddr);
      }
    }
    if (!g->shared && g->ximage) {
      g->ximage->data = NULL;
      XDestroyImage(g->ximage);
      g->ximage = NULL;
    }
  }
  if (!g->ximage) {
    char *data = calloc((size_t)stride, (size_t)g->h);
    if (!data) return 0;
    g->ximage = XCreateImage(dpy, attr->visual, (unsigned)attr->depth, ZPixmap, 0,
                             data, (unsigned)g->w, (unsigned)g->h, 32, stride);
    if (!g->ximage) { free(data); return 0; }
  }
  if (g->ximage->bits_per_pixel != 32 || g->ximage->byte_order != LSBFirst ||
      g->ximage->bytes_per_line != stride)
    return 0;
  g->work = cairo_image_surface_create_for_data((unsigned char *)g->ximage->data,
                                                CAIRO_FORMAT_RGB24, g->w, g->h, stride);
  g->pristine = cairo_image_surface_create(CAIRO_FORMAT_RGB24, g->w, g->h);
  if (cairo_surface_status(g->work) || cairo_surface_status(g->pristine)) return 0;
  /* Seed from the decoded artwork itself: no server round trip. */
  cairo_surface_flush(g->pristine);
  unsigned char *dst = cairo_image_surface_get_data(g->pristine);
  int dst_stride = cairo_image_surface_get_stride(g->pristine);
  for (int y = 0; y < g->h; ++y)
    memcpy(dst + (size_t)y * dst_stride,
           art->data + (size_t)(g->ay + y) * art->bytes_per_line + (size_t)g->ax * 4,
           (size_t)g->w * 4);
  cairo_surface_mark_dirty(g->pristine);
  return 1;
}
#endif

static void hud_set_region(Hud *hud, int i, int x, int y, int w, int h,
                           double period) {
  hud->region[i] = (HudRegion){.ax = x, .ay = y, .w = w, .h = h, .period = period};
}

/* Widget regions in artwork coordinates and their repaint periods (ms). */
static void hud_layout(Hud *hud) {
  int r = HUD_CORE_R;
  hud_set_region(hud, 0, HUD_CORE_CX - r, HUD_CORE_CY - r, 2 * r, 2 * r, 33);
  hud_set_region(hud, 1, HUD_HEX_X, HUD_HEX_Y, HUD_HEX_W,
                 HUD_HEX_ROWS * HUD_HEX_STEP, 33);  /* drawn only on change */
  hud_set_region(hud, 2, HUD_BARS_X - 2, HUD_BARS_Y - 8,
                 HUD_BARS_PCT_X - HUD_BARS_X + 4, 3 * HUD_BARS_STEP + 16, 66);
  hud_set_region(hud, 3, HUD_SUBSYS_X, HUD_SUBSYS_Y, HUD_SUBSYS_W, HUD_SUBSYS_H, 66);
  hud_set_region(hud, 4, HUD_POWER_CX - HUD_POWER_R - 8, HUD_POWER_CY - HUD_POWER_R - 8,
                 2 * (HUD_POWER_R + 8), 2 * (HUD_POWER_R + 8), 33);
  hud_set_region(hud, 14, HUD_POWER_TEXT_X - 2, HUD_POWER_TEXT_Y + 5,
                 1872 - (HUD_POWER_TEXT_X - 2), 3 * HUD_POWER_TEXT_STEP + 22, 100);
  hud_set_region(hud, 5, HUD_WAVE_X, HUD_WAVE_Y, HUD_WAVE_W, HUD_WAVE_H + 1, 33);
  hud_set_region(hud, 6, HUD_TICKER_X, HUD_TICKER_Y, HUD_TICKER_W, HUD_TICKER_H, 33);
  hud_set_region(hud, 7, HUD_DOT_X - 4, HUD_DOT_Y - 4, 14, 14, 66);
  hud_set_region(hud, 8, 10, HUD_EDGE_TOP, 6, HUD_EDGE_BOTTOM - HUD_EDGE_TOP, 33);
  hud_set_region(hud, 9, 1904, HUD_EDGE_TOP, 6, HUD_EDGE_BOTTOM - HUD_EDGE_TOP, 33);
  hud_set_region(hud, 10, HUD_READOUT_X - 2, HUD_READOUT_Y + 4, 120,
                 4 * HUD_READOUT_STEP + 22, 100);
  hud_set_region(hud, 11, HUD_WAVE_X, HUD_NET_Y - 10, HUD_WAVE_W, 20, 100);
  hud_set_region(hud, 13, HUD_THERM_BAR_X - 4, HUD_THERM_Y - 11,
                 HUD_THERM_X + 452 - (HUD_THERM_BAR_X - 4),
                 (STATS_T_COUNT - 1) * HUD_THERM_STEP + 22, 66);
  hud_set_region(hud, 12, HUD_SUBSYS_X + HUD_SUBSYS_W - HUD_SUBSYS_STATUS_W,
                 HUD_SUBSYS_Y + HUD_SUBSYS_STEP, HUD_SUBSYS_STATUS_W,
                 3 * HUD_SUBSYS_STEP + HUD_SUBSYS_H, 250);
}

static int hud_assets(Hud *hud);

/* Hover highlight 0..1, fading over 140 ms in either direction. */
static double hud_hover_mix(const Hud *hud, int action, double t) {
  double target = hud->power.hover == action ? 1 : 0;
  double k = hud->hover_t0[action] > 0 ? (t - hud->hover_t0[action]) / 140.0 : 1;
  if (k >= 1) return target;
  if (k < 0) k = 0;
  return hud->hover_from[action] + (target - hud->hover_from[action]) * k;
}

/* Validate the published numbers; anything odd means "no controls". */
#ifndef HUD_NO_X11
static int hud_power_parse(const long *v, unsigned long count, HudPowerUi *ui) {
  if (count != 11) return 0;
  HudPowerUi u = {v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7] - 1, {v[8], v[9]},
                  v[10] - 1};
  if (u.version != 2 || u.hover < -1 || u.hover > 1 || u.w <= 0 || u.w > 400 || u.h <= 0 || u.h > 200 ||
      u.gap < 0 || u.gap > 64 || (u.horizontal != 0 && u.horizontal != 1) ||
      u.pressed < -1 || u.pressed > 1 || u.status[0] < 0 || u.status[0] > 2 ||
      u.status[1] < 0 || u.status[1] > 2 || u.x < -100000 || u.x > 100000 ||
      u.y < -100000 || u.y > 100000)
    return 0;
  *ui = u;
  return 1;
}
#endif

#ifndef HUD_NO_X11
static int hud_power_read(Display *dpy, Window root, Atom atom, HudPowerUi *ui) {
  Atom type = None;
  int format = 0;
  unsigned long count = 0, after = 0;
  unsigned char *data = NULL;
  int ok = atom != None &&
           XGetWindowProperty(dpy, root, atom, 0, 11, False, XA_CARDINAL, &type,
                              &format, &count, &after, &data) == Success &&
           type == XA_CARDINAL && format == 32 && data &&
           hud_power_parse((const long *)data, count, ui);
  if (data) XFree(data);
  return ok;
}
#endif

#ifndef HUD_NO_X11
/* Place the power-controls region at artwork position (ax, ay). */
static void hud_buttons_set(Hud *hud, int ax, int ay, const HudPowerUi *ui) {
  hud->power = *ui;
  int w = (int)(ui->horizontal ? 2 * ui->w + ui->gap : ui->w);
  int h = (int)(ui->horizontal ? ui->h : 2 * ui->h + ui->gap);
  hud_set_region(hud, HUD_BUTTONS_REGION, ax, ay, w, h, 33);
  hud->power_on = 1;
}
#endif

#ifndef HUD_NO_X11
/* `art` is the decoded 1920x1200 background as validated by load_image(). */
static void hud_init(Display *dpy, XWindowAttributes *attr, XImage *art,
                     Pixmap pixmap, Window window, Hud *hud) {
  hud_destroy(dpy, hud);
  if (!art || art->width != 1920 || art->height != 1200 || attr->depth != 24 ||
      art->bits_per_pixel != 32 || art->byte_order != LSBFirst)
    return;
  hud->left = (attr->width - art->width) / 2;
  hud->top = (attr->height - art->height) / 2;
  hud_layout(hud);
  /* Power controls: drawn here only if the locker published them and the
   * panel lies within this saver window's artwork (one per monitor). */
  hud->power_root = attr->root;
  hud->power_atom = XInternAtom(dpy, "_SKYNET_POWER_UI", True);
  hud->power_shown_atom = XInternAtom(dpy, "_SKYNET_POWER_UI_SHOWN", False);
  int rx = 0, ry = 0;
  Window child;
  HudPowerUi ui;
  if (XTranslateCoordinates(dpy, window, attr->root, 0, 0, &rx, &ry, &child) &&
      hud_power_read(dpy, attr->root, hud->power_atom, &ui)) {
    hud->power_ox = rx + hud->left;
    hud->power_oy = ry + hud->top;
    int ax = (int)(ui.x - hud->power_ox), ay = (int)(ui.y - hud->power_oy);
    int w = (int)(ui.horizontal ? 2 * ui.w + ui.gap : ui.w);
    int h = (int)(ui.horizontal ? ui.h : 2 * ui.h + ui.gap);
    if (ax >= 0 && ay >= 0 && ax + w <= art->width && ay + h <= art->height)
      hud_buttons_set(hud, ax, ay, &ui);
  }
  for (int i = 0; i < HUD_REGIONS; ++i) {
    HudRegion *g = &hud->region[i];
    int x = hud->left + g->ax, y = hud->top + g->ay;
    if (x < 0 || y < 0 || x + g->w > attr->width || y + g->h > attr->height) {
      hud_destroy(dpy, hud);  /* Screen smaller than the artwork: stay static. */
      return;
    }
  }
  int major, minor;
  Bool pixmaps;
  hud->use_shm = XShmQueryVersion(dpy, &major, &minor, &pixmaps) &&
                 !getenv("SKYNET_HUD_NO_SHM");
  for (int i = 0; i < HUD_REGIONS; ++i)
    if (hud->region[i].w && !hud_region_init(dpy, attr, art, hud, &hud->region[i])) {
      hud_destroy(dpy, hud);
      return;
    }
  hud->gc = XCreateGC(dpy, pixmap, 0, NULL);
  if (!hud_assets(hud)) {
    hud_destroy(dpy, hud);
    return;
  }
  stats_init(&hud->stats, "");
  for (int i = 0; i < 4; ++i) hud->subsys[i] = -1;
  for (int i = 0; i < STATS_T_COUNT; ++i) hud->therm[i] = hud->therm_peak[i] = -1;
  hud->bat_pct = hud->bat_watts = -1;
  hud->stats_live = 1;
  hud->hex_key = -1;
  hud->ready = 1;
}

#endif

/* Fonts and the ticker strip. Returns 0 on failure. */
static int hud_assets(Hud *hud) {
  hud->font_options = cairo_font_options_create();
  cairo_font_options_set_hint_metrics(hud->font_options, CAIRO_HINT_METRICS_OFF);
  hud->regular = cairo_toy_font_face_create("JetBrains Mono", CAIRO_FONT_SLANT_NORMAL,
                                            CAIRO_FONT_WEIGHT_NORMAL);
  hud->bold = cairo_toy_font_face_create("JetBrains Mono", CAIRO_FONT_SLANT_NORMAL,
                                         CAIRO_FONT_WEIGHT_BOLD);

  cairo_t *cr;

  /* Ticker strip: one period plus the visible width, text on black (the
   * generator leaves this strip empty). */
  cairo_surface_t *probe = cairo_image_surface_create(CAIRO_FORMAT_RGB24, 1, 1);
  cr = hud_context(hud, probe);
  double width = hud_text(cr, hud->regular, 10.667, 0, 0, 0, 0, .6, hud_ticker_text);
  cairo_destroy(cr);
  cairo_surface_destroy(probe);
  hud->ticker_period = (int)lround(width);
  if (hud->ticker_period < 64 || hud->ticker_period > 4096) return 0;
  int strip_w = hud->ticker_period + HUD_TICKER_W + 1;
  hud->ticker = cairo_image_surface_create(CAIRO_FORMAT_RGB24, strip_w, HUD_TICKER_H);
  cr = hud_context(hud, hud->ticker);
  hud_rgb(cr, 0x000000, 1);
  cairo_paint(cr);
  for (double x = 0; x < strip_w; x += hud->ticker_period)
    hud_text(cr, hud->regular, 10.667, x, 16, 0x6e4750, 1, .6, hud_ticker_text);
  cairo_destroy(cr);
  return !cairo_surface_status(hud->ticker);
}

#ifndef HUD_NO_X11
static int hud_visible(const Hud *hud) { return hud->ready; }
#endif

/* Cheap deterministic hash for per-tile / per-pin variation. */
static double hud_hash(unsigned n) {
  n = (n ^ 61) ^ (n >> 16);
  n *= 9;
  n ^= n >> 4;
  n *= 0x27d4eb2d;
  n ^= n >> 15;
  return (n & 0xffff) / 65535.0;
}

static double hud_level(double v) { return v < 0 ? 0 : v > 1 ? 1 : v; }

/* CPU package: one tile per logical core fills with its live load; data
 * pulses run along the pins at a rate that follows total CPU activity. */
static void hud_core(Hud *hud, cairo_t *cr, double t) {
  const double cx = HUD_CORE_CX, cy = HUD_CORE_CY, half = HUD_PKG_HALF;
  const double activity = .12 + .88 * hud_level(hud->cpu);
  /* Pins: 12 per side; a short pulse travels inwards along busy pins. */
  for (int side = 0; side < 4; ++side) {
    for (int k = 0; k < HUD_PINS; ++k) {
      unsigned id = (unsigned)(side * HUD_PINS + k);
      if (hud_hash(id * 7 + 1) > activity) continue;
      double speed = 520 + 380 * hud_hash(id * 13 + 5);
      double u = fmod(t / speed + hud_hash(id), 1.0);
      double along = -half + 16 + k * (2 * half - 32) / (HUD_PINS - 1);
      double out = half + HUD_PIN_LEN * (1 - u), in = out - 5;
      double x0, y0, x1, y1;
      switch (side) {
        case 0: x0 = cx + along; y0 = cy - out; x1 = x0; y1 = cy - in; break;
        case 1: x0 = cx + out; y0 = cy + along; x1 = cx + in; y1 = y0; break;
        case 2: x0 = cx + along; y0 = cy + out; x1 = x0; y1 = cy + in; break;
        default: x0 = cx - out; y0 = cy + along; x1 = cx - in; y1 = y0; break;
      }
      hud_rgb(cr, 0xff6070, .35 + .65 * (1 - u));
      cairo_set_line_width(cr, 2);
      cairo_move_to(cr, x0, y0); cairo_line_to(cr, x1, y1); cairo_stroke(cr);
    }
  }
  /* Core tiles, 4x4, row-major from the top-left. */
  const double span = 4 * HUD_TILE + 3 * HUD_TILE_GAP;
  const double left = cx - span / 2, top = cy - span / 2;
  for (int i = 0; i < 16; ++i) {
    double x = left + (i % 4) * (HUD_TILE + HUD_TILE_GAP);
    double y = top + (i / 4) * (HUD_TILE + HUD_TILE_GAP);
    double load = hud_level(hud->core[i]);
    int present = i < hud->stats.cores || !hud->stats_live;
    if (present && load > .005) {
      double h = 2 + (HUD_TILE - 2) * load;
      cairo_pattern_t *fill = cairo_pattern_create_linear(0, y + HUD_TILE - h, 0, y + HUD_TILE);
      cairo_pattern_add_color_stop_rgba(fill, 0, 1, .25, .31, .25 + .45 * load);
      cairo_pattern_add_color_stop_rgba(fill, 1, 1, .25, .31, .08 + .2 * load);
      cairo_set_source(cr, fill);
      cairo_rectangle(cr, x + 1, y + HUD_TILE - h, HUD_TILE - 2, h - 1);
      cairo_fill(cr);
      cairo_pattern_destroy(fill);
    }
    hud_rgb(cr, load > .75 ? 0xff4050 : 0xc42a3e, present ? .25 + .75 * load : .15);
    cairo_set_line_width(cr, 1);
    cairo_rectangle(cr, x + .5, y + .5, HUD_TILE - 1, HUD_TILE - 1);
    cairo_stroke(cr);
    /* Activity LED blinks faster the busier the core is. */
    double rate = 900 - 760 * load;
    int on = present && fmod(t + 997 * hud_hash((unsigned)i + 40), rate) < rate * (.25 + .5 * load);
    hud_rgb(cr, on ? 0xff6070 : 0x3a1018, 1);
    cairo_rectangle(cr, x + HUD_TILE - 7, y + 4, 3, 3);
    cairo_fill(cr);
    char label[4];
    snprintf(label, sizeof(label), "%02d", i);
    hud_text(cr, hud->regular, 8, x + 4, y + 11, load > .5 ? 0xe6dbde : 0x6e4750,
             present ? 1 : .4, 0, label);
  }
  /* A faint scan line sweeps the die. */
  double sy = top - 4 + fmod(t, 2600.0) / 2600.0 * (span + 8);
  cairo_pattern_t *scan = cairo_pattern_create_linear(0, sy - 10, 0, sy);
  cairo_pattern_add_color_stop_rgba(scan, 0, 1, .25, .31, 0);
  cairo_pattern_add_color_stop_rgba(scan, 1, 1, .25, .31, .22);
  cairo_set_source(cr, scan);
  cairo_rectangle(cr, left - 4, sy - 10, span + 8, 10);
  cairo_fill(cr);
  cairo_pattern_destroy(scan);
}

/* Readouts next to the package: CORES, LOAD, TEMP, CLOCK, MODE. */
static void hud_readouts(Hud *hud, cairo_t *cr) {
  char value[5][24];
  const SysStats *s = &hud->stats;
  int cores = hud->stats_live ? s->cores : 16;
  snprintf(value[0], sizeof(value[0]), cores > 0 ? "%02d" : "--", cores);
  snprintf(value[1], sizeof(value[1]), hud->cpu >= 0 ? "%d%%" : "--",
           (int)lround(hud_level(hud->cpu) * 100));
  snprintf(value[2], sizeof(value[2]), s->temp > 0 ? "%d\xc2\xb0" "C" : "--",
           (int)lround(s->temp));
  snprintf(value[3], sizeof(value[3]), s->ghz > 0 ? "%.1f GHZ" : "--", s->ghz);
  snprintf(value[4], sizeof(value[4]), "%s", s->mode);
  for (int i = 0; i < 5; ++i) {
    int hot = (i == 1 && hud->cpu > .85) || (i == 2 && s->temp > 85);
    /* Long profile names (e.g. BALANCED-PERFORMANCE) shrink to fit. */
    double size = 13.333;
    cairo_text_extents_t e;
    cairo_set_font_face(cr, hud->bold);
    cairo_set_font_size(cr, size);
    cairo_text_extents(cr, value[i], &e);
    if (e.x_advance > 108) size *= 108 / e.x_advance;
    hud_text(cr, hud->bold, size, HUD_READOUT_X,
             HUD_READOUT_Y + 16 + 4.5 + i * HUD_READOUT_STEP,
             hot ? 0xff4050 : 0x8a9099, 1, 0, value[i]);
  }
}

static void hud_hex(Hud *hud, cairo_t *cr, double t) {
  int scroll = (int)(t / 900.0);          /* memory scrolls one row per 0.9 s */
  int hot = (int)(t / 220.0) % HUD_HEX_ROWS; /* scan line walks down */
  const int words = (int)(sizeof(hud_words) / sizeof(hud_words[0]));
  for (int i = 0; i < HUD_HEX_ROWS; ++i) {
    double y = HUD_HEX_Y + 9 + i * HUD_HEX_STEP;
    int row = scroll + i, is_hot = i == hot;
    if (is_hot) {
      hud_rgb(cr, 0x2a0a10, 1);
      cairo_rectangle(cr, HUD_HEX_X, y - 9, HUD_HEX_W, 18); cairo_fill(cr);
      hud_rgb(cr, 0xff4050, 1);
      cairo_rectangle(cr, HUD_HEX_X, y - 9, 2, 18); cairo_fill(cr);
    }
    char address[16], bytes[64];
    snprintf(address, sizeof(address), "0x%06X", 0x7F3A00 + (row & 0xFFFF) * 16);
    snprintf(bytes, sizeof(bytes), "%s  %s  %s", hud_words[row % words],
             hud_words[(row + 3) % words], hud_words[(row + 7) % words]);
    hud_text(cr, hud->regular, 10.667, HUD_HEX_X + 10, y + 4,
             is_hot ? 0xc42a3e : 0x6e4750, 1, 0, address);
    hud_text(cr, hud->regular, 10.667, HUD_HEX_X + 100, y + 4,
             is_hot ? 0xe6dbde : 0x4a5058, 1, 0, bytes);
    if (is_hot) {
      double blink = fmod(t, 440.0) < 300 ? 1 : .35;
      hud_text(cr, hud->regular, 10.667, HUD_HEX_X + HUD_HEX_W - 50, y + 4,
               0xff4050, blink, 0, "\xe2\x97\x82 EXEC");
    }
  }
}

static void hud_bars(Hud *hud, cairo_t *cr, double t) {
  const double values[4] = {hud->cpu, hud->mem, hud->swap, hud->disk};
  const int count = 26, gap = 3;
  const double seg = (HUD_BARS_W - gap * (count - 1)) / (double)count;
  for (int i = 0; i < 4; ++i) {
    double level = hud_level(values[i]);
    /* The lead segment breathes so idle bars still look alive. */
    double breathe = .5 + .5 * sin(t / 420.0 + i * 1.9);
    double y = HUD_BARS_Y + i * HUD_BARS_STEP - 3;
    int lit = (int)lround(level * count);
    if (lit < 1) lit = 1;
    for (int s = 0; s < count; ++s) {
      unsigned color = s < lit ? (s >= count - 3 ? 0xff6070 : 0xff4050) : 0x2a0a10;
      hud_rgb(cr, color, s == lit - 1 ? .45 + .55 * breathe : 1);
      cairo_rectangle(cr, HUD_BARS_X + s * (seg + gap), y, seg, 5);
      cairo_fill(cr);
    }
    char pct[8];
    if (values[i] < 0) snprintf(pct, sizeof(pct), " --");
    else snprintf(pct, sizeof(pct), "%3d%%", (int)lround(level * 100));
    cairo_text_extents_t e;
    cairo_set_font_face(cr, hud->regular);
    cairo_set_font_size(cr, 10.667);
    cairo_text_extents(cr, pct, &e);
    hud_text(cr, hud->regular, 10.667, HUD_BARS_PCT_X - e.x_advance, y + 7,
             level > .9 ? 0xe6dbde : 0x8a9099, 1, 0, pct);
  }
}

/* Subsystem rows 1-4: invented names, real (aggregate) inputs. Level 0..2
 * maps to calm / elevated / critical; a small band avoids flicker. */
static const char *const hud_subsys_words[4][3] = {
  {"NOMINAL", "ELEVATED", "CRITICAL"},  /* MEMORY.MANAGER: memory use */
  {"COOL", "WARM", "HOT"},              /* THERMAL.CONTROL: package temp */
  {"IDLE", "ACTIVE", "BUSY"},           /* NETWORK.UPLINK: throughput */
  {"IDLE", "ACTIVE", "BUSY"},           /* STORAGE.ARRAY: disk busy */
};

static int hud_subsys_level(int previous, double value, double low, double high,
                            double band) {
  if (value < 0) return -1;
  int level = value >= high ? 2 : value >= low ? 1 : 0;
  if (previous >= 0 && level != previous) {
    /* Stay put until the value clears the boundary by `band`. */
    double edge = level > previous ? (previous == 0 ? low : high)
                                   : (previous == 2 ? high : low);
    if (fabs(value - edge) < band) return previous;
  }
  return level;
}

static void hud_subsys_update(Hud *hud) {
  const SysStats *s = &hud->stats;
  double rate = s->rx < 0 && s->tx < 0 ? -1
                : (s->rx > 0 ? s->rx : 0) + (s->tx > 0 ? s->tx : 0);
  hud->subsys[0] = hud_subsys_level(hud->subsys[0], hud->mem, .70, .90, .02);
  hud->subsys[1] = hud_subsys_level(hud->subsys[1], s->temp, 60, 80, 2);
  hud->subsys[2] = hud_subsys_level(hud->subsys[2], rate, 10e3, 1e6, 0);
  hud->subsys[3] = hud_subsys_level(hud->subsys[3], hud->disk, .05, .60, .02);
}

static void hud_subsys(Hud *hud, cairo_t *cr, double t) {
  for (int i = 0; i < 4; ++i) {
    int level = hud->subsys[i];
    const char *word = level < 0 ? "N/A" : hud_subsys_words[i][level];
    unsigned color = level == 2 ? 0xff4050 : level == 1 ? 0xe6dbde : 0x6e4750;
    double alpha = level == 2 ? .6 + .4 * (.5 + .5 * sin(t / 160.0)) : 1;
    double cy = HUD_SUBSYS_Y + HUD_SUBSYS_H / 2.0 + (i + 1) * HUD_SUBSYS_STEP;
    cairo_text_extents_t e;
    cairo_set_font_face(cr, hud->bold);
    cairo_set_font_size(cr, 10.667);
    cairo_text_extents(cr, word, &e);
    /* Letter spacing 1 px per glyph, like the static art. */
    double width = e.x_advance + strlen(word);
    double right = HUD_SUBSYS_X + HUD_SUBSYS_W - 10;
    hud_text(cr, hud->bold, 10.667, right - width, cy + 3.5, color, alpha, 1, word);
    if (level >= 1) {
      hud_rgb(cr, color, alpha);
      cairo_arc(cr, right - width - 9, cy, 2.5, 0, 2 * HUD_PI);
      cairo_fill(cr);
    }
  }
}

/* THERMAL // SENSORS: one thermometer per sensor kind on a 20-100 C scale.
 * The fill shifts steel -> red with heat, a highlight drifts along it, the
 * session peak keeps a thin tick and anything from 80 C pulses red. */
static void hud_thermal(Hud *hud, cairo_t *cr, double t) {
  const double bx = HUD_THERM_BAR_X, bw = HUD_THERM_BAR_W;
  const double right = HUD_THERM_X + 452;
  for (int i = 0; i < STATS_T_COUNT; ++i) {
    double cy = HUD_THERM_Y + i * HUD_THERM_STEP, v = hud->therm[i];
    char value[16];
    unsigned color = 0x6e4750;
    double alpha = 1;
    if (v >= 0) {
      double u = (v - HUD_THERM_MIN) / (HUD_THERM_MAX - HUD_THERM_MIN);
      u = u < .02 ? .02 : u > 1 ? 1 : u;
      int hot = v >= 80;
      double pulse = .5 + .5 * sin(t / 160.0);
      color = hot ? 0xff4050 : v >= 60 ? 0xe6dbde : 0x8a9099;
      alpha = hot ? .6 + .4 * pulse : 1;
      /* Fill: gradient pinned to the scale, so colour means temperature. */
      cairo_pattern_t *fill = cairo_pattern_create_linear(bx, 0, bx + bw, 0);
      cairo_pattern_add_color_stop_rgb(fill, 0, .29, .31, .35);
      cairo_pattern_add_color_stop_rgb(fill, .5, .77, .16, .24);
      cairo_pattern_add_color_stop_rgb(fill, 1, 1, .25, .31);
      cairo_set_source(cr, fill);
      cairo_rectangle(cr, bx, cy - 2, u * bw, 4);
      cairo_fill(cr);
      cairo_pattern_destroy(fill);
      /* Drifting highlight inside the filled part. */
      double p = bx + fmod(t / 2600.0 + i * .21, 1.0) * (u * bw + 24) - 12;
      cairo_pattern_t *shine = cairo_pattern_create_linear(p - 12, 0, p + 12, 0);
      cairo_pattern_add_color_stop_rgba(shine, 0, .9, .86, .87, 0);
      cairo_pattern_add_color_stop_rgba(shine, .5, .9, .86, .87, .45);
      cairo_pattern_add_color_stop_rgba(shine, 1, .9, .86, .87, 0);
      cairo_save(cr);
      cairo_rectangle(cr, bx, cy - 2, u * bw, 4);
      cairo_clip(cr);
      cairo_set_source(cr, shine);
      cairo_paint(cr);
      cairo_restore(cr);
      cairo_pattern_destroy(shine);
      /* Session peak tick. */
      double pk = (hud->therm_peak[i] - HUD_THERM_MIN) / (HUD_THERM_MAX - HUD_THERM_MIN);
      if (pk > u + .01 && pk <= 1) {
        hud_rgb(cr, 0x8a9099, .6);
        cairo_rectangle(cr, bx + pk * bw - .5, cy - 5, 1, 10);
        cairo_fill(cr);
      }
      /* Bright tip, with a glow when hot. */
      double tip = bx + u * bw;
      if (hot) {
        hud_rgb(cr, 0xff4050, .15 + .25 * pulse);
        cairo_rectangle(cr, tip - 4, cy - 7, 6, 14);
        cairo_fill(cr);
      }
      hud_rgb(cr, hot ? 0xff6070 : 0xe6dbde, 1);
      cairo_rectangle(cr, tip - 2, cy - 5, 2, 10);
      cairo_fill(cr);
      snprintf(value, sizeof(value), "%d\xc2\xb0" "C", (int)lround(v));
    } else {
      snprintf(value, sizeof(value), "N/A");
    }
    double width = hud_text(cr, hud->bold, 12, -10000, -10000, 0, 0, 0, value);
    hud_text(cr, hud->bold, 12, right - width, cy + 4, color, alpha, 0, value);
  }
}

/* Reboot / shut down controls in the HUD style. Reboot has a steel accent,
 * shut down a red one; a refused action turns red. The locker owns the
 * behaviour; this only shows the state it publishes. */
static void hud_button_icon(cairo_t *cr, int action, double cx, double cy,
                            double spin) {
  cairo_set_line_cap(cr, CAIRO_LINE_CAP_ROUND);
  cairo_set_line_width(cr, 2);
  if (action == 0) {
    double a0 = -HUD_PI / 2 + .55 + spin, a1 = a0 + 2 * HUD_PI - 1.0;
    cairo_new_sub_path(cr);
    cairo_arc(cr, cx, cy, 8.5, a0, a1);
    cairo_stroke(cr);
    /* Arrowhead at the end of the arc, pointing along it. */
    double ex = cx + 8.5 * cos(a1), ey = cy + 8.5 * sin(a1);
    double tx = -sin(a1), ty = cos(a1), nx = cos(a1), ny = sin(a1);
    cairo_move_to(cr, ex + tx * 4.5, ey + ty * 4.5);
    cairo_line_to(cr, ex - nx * 3.5 - tx * 1.5, ey - ny * 3.5 - ty * 1.5);
    cairo_line_to(cr, ex + nx * 3.5 - tx * 1.5, ey + ny * 3.5 - ty * 1.5);
    cairo_close_path(cr);
    cairo_fill(cr);
  } else {
    cairo_new_sub_path(cr);
    cairo_arc(cr, cx, cy + 1, 8.5, -HUD_PI / 2 + .75, -HUD_PI / 2 + 2 * HUD_PI - .75);
    cairo_stroke(cr);
    cairo_move_to(cr, cx, cy - 10);
    cairo_line_to(cr, cx, cy - 1);
    cairo_stroke(cr);
  }
  cairo_set_line_cap(cr, CAIRO_LINE_CAP_BUTT);
}

static void hud_button(Hud *hud, cairo_t *cr, double t, int action, double x,
                       double y, double w, double h) {
  static const char *const title[2][3] = {
    {"REBOOT", "REBOOTING", "BLOCKED"}, {"SHUT DOWN", "SHUTTING DOWN", "BLOCKED"}};
  static const char *const sub[2][3] = {
    {"SYS.RESTART", "STAND BY", "ACTION REFUSED"},
    {"SYS.HALT", "STAND BY", "ACTION REFUSED"}};
  int status = (int)hud->power.status[action];
  int pressed = hud->power.pressed == action;
  unsigned accent = action ? 0xff4050 : 0xb8bec6;
  if (status == 2) accent = 0xff4050;
  unsigned edge = action || status == 2 ? 0x5a1520 : 0x3a3f46;
  double breath = .5 + .5 * sin(t / 900.0 + action * 1.7);
  double hover = pressed ? 1 : hud_hover_mix(hud, action, t);
  double ar = ((accent >> 16) & 255) / 255.0, ag = ((accent >> 8) & 255) / 255.0,
         ab = (accent & 255) / 255.0;
  /* Body; hovering tints it towards the accent. */
  hud_rgb(cr, pressed ? (action ? 0x2a0a10 : 0x1a1d22) : status ? 0x150609 : 0x0b0406, 1);
  cairo_rectangle(cr, x, y, w, h);
  cairo_fill(cr);
  if (hover > 0 && !pressed) {
    cairo_pattern_t *tint = cairo_pattern_create_linear(x, 0, x + w, 0);
    cairo_pattern_add_color_stop_rgba(tint, 0, ar, ag, ab, .13 * hover);
    cairo_pattern_add_color_stop_rgba(tint, 1, ar, ag, ab, .03 * hover);
    cairo_rectangle(cr, x, y, w, h);
    cairo_set_source(cr, tint);
    cairo_fill(cr);
    cairo_pattern_destroy(tint);
  }
  /* Glint: occasional and staggered at rest, a quick loop on hover. */
  double period = hover > .5 ? 1400.0 : 5200.0;
  double cycle = fmod(t + action * 2600.0, period) / period;
  if (cycle < .3 && status != 2) {
    double gx = x - 60 + (w + 120) * (cycle / .3);
    cairo_pattern_t *glint = cairo_pattern_create_linear(gx - 50, 0, gx + 50, 0);
    cairo_pattern_add_color_stop_rgba(glint, 0, 1, .4, .45, 0);
    cairo_pattern_add_color_stop_rgba(glint, .5, 1, .4, .45, .07 + .08 * hover);
    cairo_pattern_add_color_stop_rgba(glint, 1, 1, .4, .45, 0);
    cairo_rectangle(cr, x, y, w, h);
    cairo_set_source(cr, glint);
    cairo_fill(cr);
    cairo_pattern_destroy(glint);
  }
  /* Frame, corner brackets and the icon cell. */
  hud_rgb(cr, edge, 1);
  cairo_set_line_width(cr, 1);
  cairo_rectangle(cr, x + .5, y + .5, w - 1, h - 1);
  cairo_stroke(cr);
  if (hover > 0) {
    hud_rgb(cr, accent, .8 * hover);
    cairo_rectangle(cr, x + .5, y + .5, w - 1, h - 1);
    cairo_stroke(cr);
  }
  double bracket = pressed || status ? 1 : .55 + .35 * breath;
  hud_rgb(cr, accent, bracket + (1 - bracket) * hover);
  cairo_set_line_width(cr, 2);
  const double L = 9 + 6 * hover;
  double cx0[2] = {x + 1, x + w - 1}, cy0[2] = {y + 1, y + h - 1};
  for (int i = 0; i < 2; ++i)
    for (int j = 0; j < 2; ++j) {
      double sx = i ? -1 : 1, sy = j ? -1 : 1;
      cairo_move_to(cr, cx0[i], cy0[j] + sy * L);
      cairo_line_to(cr, cx0[i], cy0[j]);
      cairo_line_to(cr, cx0[i] + sx * L, cy0[j]);
    }
  cairo_stroke(cr);
  hud_rgb(cr, edge, 1);
  cairo_set_line_width(cr, 1);
  cairo_move_to(cr, x + h + .5, y + 10);
  cairo_line_to(cr, x + h + .5, y + h - 10);
  cairo_stroke(cr);
  double spin = status == 1 && action == 0 ? t / 220.0 : 0;
  double icon_alpha = status == 1 && action == 1 ? .45 + .55 * breath : 1;
  hud_rgb(cr, accent, icon_alpha);
  hud_button_icon(cr, action, x + h / 2, y + h / 2, spin);
  /* Title (shrinks to fit) and subtitle. */
  const char *head = title[action][status];
  double tx = x + h + 14, room = w - h - 14 - 50;
  double size = 12, spacing = 2;
  double width = hud_text(cr, hud->bold, size, -10000, -10000, 0, 0, spacing, head);
  if (width > room) size *= room / width, spacing *= room / width;
  unsigned head_color = status == 2 ? 0xff4050 : pressed || hover > .5 ? accent : 0xe6dbde;
  hud_text(cr, hud->bold, size, tx, y + h / 2 - 2, head_color, 1, spacing, head);
  if (hover > 0 && status == 0) {
    /* Underline grows under the title while hovered. */
    double uw = hud_text(cr, hud->bold, size, -10000, -10000, 0, 0, spacing, head) - spacing;
    hud_rgb(cr, accent, .9);
    cairo_rectangle(cr, tx, y + h / 2 + 2, uw * hover, 1);
    cairo_fill(cr);
  }
  double sub_alpha = status == 1 ? .35 + .65 * (fmod(t, 900.0) < 600) : 1;
  hud_text(cr, hud->regular, 8, tx, y + h / 2 + 13, status == 2 ? 0xc42a3e : 0x6e4750,
           sub_alpha, 1, sub[action][status]);
  /* Key cap. */
  const char *key = action ? "F12" : "F11";
  double kx = x + w - 44, ky = y + h / 2 - 9;
  if (hover > 0) {
    hud_rgb(cr, accent, .85 * hover);
    cairo_rectangle(cr, kx, ky, 32, 18);
    cairo_fill(cr);
  }
  hud_rgb(cr, accent, .6 + .4 * hover);
  cairo_rectangle(cr, kx + .5, ky + .5, 31, 17);
  cairo_stroke(cr);
  double kw = hud_text(cr, hud->bold, 9, -10000, -10000, 0, 0, 0, key);
  hud_text(cr, hud->bold, 9, kx + 16 - kw / 2, ky + 12.5, hover > .5 ? 0x0b0406 : accent,
           1, 0, key);
  /* Pending: dashes run along the bottom edge. */
  if (status == 1) {
    double shift = fmod(t / 12.0, 16.0);
    cairo_save(cr);
    cairo_rectangle(cr, x + 2, y + h - 4, w - 4, 2);
    cairo_clip(cr);
    hud_rgb(cr, accent, .9);
    for (double dx = x - 16 + shift; dx < x + w; dx += 16) {
      cairo_rectangle(cr, dx, y + h - 4, 9, 2);
    }
    cairo_fill(cr);
    cairo_restore(cr);
  }
}

static void hud_buttons(Hud *hud, cairo_t *cr, double t) {
  if (!hud->power_on) return;
  const HudRegion *g = &hud->region[HUD_BUTTONS_REGION];
  const HudPowerUi *ui = &hud->power;
  for (int action = 0; action < 2; ++action) {
    double x = g->ax + (action && ui->horizontal ? ui->w + ui->gap : 0);
    double y = g->ay + (action && !ui->horizontal ? ui->h + ui->gap : 0);
    hud_button(hud, cr, t, action, x, y, (double)ui->w, (double)ui->h);
  }
}

static void hud_threat(Hud *hud, cairo_t *cr, double t) {
  double pulse = .5 + .5 * sin(t * 2 * HUD_PI / 1600.0);
  const double x = HUD_SUBSYS_X, y = HUD_SUBSYS_Y, w = HUD_SUBSYS_W, h = HUD_SUBSYS_H;
  hud_rgb(cr, 0x2a0a10, 1);
  cairo_rectangle(cr, x, y, w, h); cairo_fill(cr);
  hud_rgb(cr, 0xff4050, .05 + .12 * pulse);
  cairo_rectangle(cr, x, y, w, h); cairo_fill(cr);
  hud_rgb(cr, 0xff4050, 1);
  cairo_rectangle(cr, x, y, 2, h); cairo_fill(cr);
  /* Scanning highlight sweeping across the row every 2.4 s. */
  double sx = x + fmod(t, 2400.0) / 2400.0 * (w + 120) - 120;
  cairo_pattern_t *band = cairo_pattern_create_linear(sx, 0, sx + 120, 0);
  cairo_pattern_add_color_stop_rgba(band, 0, 1, .25, .31, 0);
  cairo_pattern_add_color_stop_rgba(band, .5, 1, .25, .31, .16);
  cairo_pattern_add_color_stop_rgba(band, 1, 1, .25, .31, 0);
  cairo_set_source(cr, band);
  cairo_rectangle(cr, x + 2, y, w - 2, h); cairo_fill(cr);
  cairo_pattern_destroy(band);
  hud_text(cr, hud->regular, 12, x + 12, y + 15, 0xe6dbde, 1, 0, "SKYNET.KERNEL");
  cairo_text_extents_t e;
  cairo_set_font_face(cr, hud->bold);
  cairo_set_font_size(cr, 10.667);
  cairo_text_extents(cr, "ONLINE", &e);
  double right = x + w - 10 - (e.x_advance + 5);
  hud_text(cr, hud->bold, 10.667, right, y + 15, 0xff4050, .6 + .4 * pulse, 1, "ONLINE");
  hud_rgb(cr, 0xff4050, .3 + .7 * pulse);
  cairo_arc(cr, right - 10, y + h / 2, 3, 0, 2 * HUD_PI); cairo_fill(cr);
}

/* POWER // BATTERY: 40-segment charge ring, energy-flow ring and the
 * charge in the middle. Data: the system battery only (sys-stats.h). */
static void hud_power(Hud *hud, cairo_t *cr, double t) {
  const double cx = HUD_POWER_CX, cy = HUD_POWER_CY;
  const SysStats *s = &hud->stats;
  double pct = hud->bat_pct;
  int state = s->bat_state;
  double pulse = .5 + .5 * sin(t / 180.0);
  int low = pct >= 0 && pct < .2 && state == STATS_BAT_DISCHARGING;
  int lit = pct < 0 ? 0 : (int)lround(pct * HUD_POWER_SEGMENTS);
  if (pct > 0 && lit < 1) lit = 1;
  /* Charging: a bright sweep runs from empty up to the current level. */
  double sweep = state == STATS_BAT_CHARGING ? fmod(t, 1600.0) / 1600.0 * lit : -10;
  const double seg = 2 * HUD_PI / HUD_POWER_SEGMENTS;
  cairo_set_line_cap(cr, CAIRO_LINE_CAP_BUTT);
  cairo_set_line_width(cr, 7);
  for (int i = 0; i < lit; ++i) {
    double a = -HUD_PI / 2 + i * seg + .02;
    double alpha = low ? .45 + .55 * pulse : i == lit - 1 ? .55 + .45 * pulse : .9;
    double glow = 1 - fabs(i - sweep) / 3;
    if (glow > 0) alpha = alpha + (1 - alpha) * glow;
    hud_rgb(cr, glow > .3 ? 0xffb0b8 : 0xff4050, alpha);
    cairo_new_sub_path(cr);
    cairo_arc(cr, cx, cy, HUD_POWER_R, a, a + seg - .06);
    cairo_stroke(cr);
  }
  /* Energy flow ring: dashes travel with the current, still when idle. */
  int moving = state == STATS_BAT_CHARGING || state == STATS_BAT_DISCHARGING;
  unsigned flow = state == STATS_BAT_DISCHARGING ? 0xff4050
                  : state == STATS_BAT_CHARGING ? 0xe6dbde : 0x8a9099;
  cairo_set_line_width(cr, 2);
  for (int k = 0; k < 12; ++k) {
    double a = hud->flow_phase * 2 * HUD_PI / 3 + k * HUD_PI / 6;
    hud_rgb(cr, flow, moving ? .85 : .25 + .15 * pulse);
    cairo_new_sub_path(cr);
    cairo_arc(cr, cx, cy, HUD_POWER_INNER, a, a + .22);
    cairo_stroke(cr);
  }
  /* Charge, centred. */
  char text[16];
  if (pct >= 0) snprintf(text, sizeof(text), "%d%%", (int)lround(pct * 100));
  else snprintf(text, sizeof(text), "--");
  double width = hud_text(cr, hud->bold, 22, -10000, -10000, 0, 0, 0, text);
  hud_text(cr, hud->bold, 22, cx - width / 2, cy + 5, low ? 0xff4050 : 0xe6dbde,
           low ? .6 + .4 * pulse : 1, 0, text);
}

static void hud_power_text(Hud *hud, cairo_t *cr, double t) {
  const SysStats *s = &hud->stats;
  static const char *const states[] = {"--", "CHARGING", "DISCHARGING", "FULL", "HOLD"};
  char value[4][24];
  int state = s->bat_state >= 0 && s->bat_state <= STATS_BAT_HOLD ? s->bat_state : 0;
  snprintf(value[0], sizeof(value[0]), "%s", states[state]);
  if (hud->bat_watts >= 0) snprintf(value[1], sizeof(value[1]), "%.1f W", hud->bat_watts);
  else snprintf(value[1], sizeof(value[1]), "--");
  if (s->bat_health >= 0) snprintf(value[2], sizeof(value[2]), "%.1f%%", s->bat_health * 100);
  else snprintf(value[2], sizeof(value[2]), "--");
  if (s->bat_cycles >= 0) snprintf(value[3], sizeof(value[3]), "%d", s->bat_cycles);
  else snprintf(value[3], sizeof(value[3]), "--");
  double pulse = .5 + .5 * sin(t / 180.0);
  for (int i = 0; i < 4; ++i) {
    unsigned color = 0x8a9099;
    double alpha = 1;
    if (i == 0 && state == STATS_BAT_DISCHARGING) {
      color = 0xff4050;
      alpha = hud->bat_pct >= 0 && hud->bat_pct < .2 ? .6 + .4 * pulse : 1;
    } else if (i == 0 && state == STATS_BAT_CHARGING) {
      color = 0xe6dbde;
    }
    hud_text(cr, hud->bold, 13.333, HUD_POWER_TEXT_X,
             HUD_POWER_TEXT_Y + 16 + 4.5 + i * HUD_POWER_TEXT_STEP, color, alpha, 0, value[i]);
  }
}

/* Real network traffic: the last ~60 s of RX (filled) and TX (line),
 * scrolling smoothly from right to left on an auto-scaled linear axis. */
static void hud_net_push(Hud *hud, double t, double rx, double tx) {
  if (rx < 0 && tx < 0) return;
  int n = hud->net_count < HUD_NET_HISTORY ? hud->net_count + 1 : HUD_NET_HISTORY;
  memmove(hud->net_t + 1, hud->net_t, (size_t)(n - 1) * sizeof(double));
  memmove(hud->net_rx + 1, hud->net_rx, (size_t)(n - 1) * sizeof(double));
  memmove(hud->net_tx + 1, hud->net_tx, (size_t)(n - 1) * sizeof(double));
  hud->net_t[0] = t;
  hud->net_rx[0] = rx > 0 ? rx : 0;
  hud->net_tx[0] = tx > 0 ? tx : 0;
  hud->net_count = n;
}

static double hud_net_x(double t, double sample_t) {
  return HUD_WAVE_X + HUD_WAVE_W - (t - sample_t) / HUD_NET_WINDOW * HUD_WAVE_W;
}

static double hud_net_y(const Hud *hud, double rate) {
  double scale = hud->net_scale > HUD_NET_FLOOR ? hud->net_scale : HUD_NET_FLOOR;
  double u = rate / scale;
  if (u > 1) u = 1;
  return HUD_WAVE_Y + HUD_WAVE_H - 1 - u * (HUD_WAVE_H - 8);
}

static void hud_wave(Hud *hud, cairo_t *cr, double t) {
  const double x0 = HUD_WAVE_X, w = HUD_WAVE_W, bottom = HUD_WAVE_Y + HUD_WAVE_H - 1;
  cairo_save(cr);
  cairo_rectangle(cr, x0, HUD_WAVE_Y, w, HUD_WAVE_H + 1);
  cairo_clip(cr);
  int n = hud->net_count;
  if (n > 0) {
    /* Hold the newest value up to the right edge ("now"). */
    for (int series = 0; series < 2; ++series) {
      const double *v = series ? hud->net_tx : hud->net_rx;
      cairo_new_path(cr);
      cairo_move_to(cr, x0 + w, hud_net_y(hud, v[0]));
      for (int i = 0; i < n; ++i) {
        double x = hud_net_x(t, hud->net_t[i]);
        cairo_line_to(cr, x, hud_net_y(hud, v[i]));
        if (x < x0) break;
      }
      if (!series) {
        cairo_path_t *line = cairo_copy_path(cr);
        double lx, ly;
        cairo_get_current_point(cr, &lx, &ly);
        cairo_line_to(cr, lx, bottom);
        cairo_line_to(cr, x0 + w, bottom);
        cairo_close_path(cr);
        cairo_pattern_t *fill = cairo_pattern_create_linear(0, HUD_WAVE_Y, 0, bottom);
        cairo_pattern_add_color_stop_rgba(fill, 0, 1, .25, .31, .32);
        cairo_pattern_add_color_stop_rgba(fill, 1, 1, .25, .31, .03);
        cairo_set_source(cr, fill);
        cairo_fill(cr);
        cairo_pattern_destroy(fill);
        cairo_append_path(cr, line);
        cairo_path_destroy(line);
        hud_rgb(cr, 0xff4050, 1);
        cairo_set_line_width(cr, 1.5);
      } else {
        hud_rgb(cr, 0xb8bec6, .8);
        cairo_set_line_width(cr, 1.2);
      }
      cairo_set_line_join(cr, CAIRO_LINE_JOIN_BEVEL);
      cairo_stroke(cr);
    }
    /* "Now" cursor: newest RX point glows on the right edge. */
    double pulse = .5 + .5 * sin(t / 200.0);
    double ny = hud_net_y(hud, hud->net_rx[0]);
    hud_rgb(cr, 0xff4050, .18 + .22 * pulse);
    cairo_arc(cr, x0 + w - 4, ny, 5 + 2 * pulse, 0, 2 * HUD_PI);
    cairo_fill(cr);
    hud_rgb(cr, 0xff6070, 1);
    cairo_arc(cr, x0 + w - 4, ny, 2.2, 0, 2 * HUD_PI);
    cairo_fill(cr);
  }
  /* Full-scale label, top left of the plot. */
  char scale[24], label[32];
  stats_format_rate(hud->net_scale > HUD_NET_FLOOR ? hud->net_scale : HUD_NET_FLOOR,
                    scale, sizeof(scale));
  snprintf(label, sizeof(label), "MAX %s", scale);
  hud_text(cr, hud->regular, 8, x0 + 2, HUD_WAVE_Y + 9, 0x6e4750, 1, 1, label);
  cairo_restore(cr);
}

static void hud_net(Hud *hud, cairo_t *cr) {
  char rx[24], tx[24];
  stats_format_rate(hud->stats.rx, rx, sizeof(rx));
  stats_format_rate(hud->stats.tx, tx, sizeof(tx));
  const double y = HUD_NET_Y + 3.5;
  double x = HUD_WAVE_X;
  x += hud_text(cr, hud->regular, 10.667, x, y, 0x5a4048, 1, 1, "RX  ");
  hud_text(cr, hud->regular, 10.667, x, y, 0xff6070, 1, 1, rx);
  /* Right-aligned TX: measure first, then draw. */
  double width = hud_text(cr, hud->regular, 10.667, -10000, -10000, 0, 0, 1, "TX  ") +
                 hud_text(cr, hud->regular, 10.667, -10000, -10000, 0, 0, 1, tx);
  x = HUD_WAVE_X + HUD_WAVE_W - width;
  x += hud_text(cr, hud->regular, 10.667, x, y, 0x5a4048, 1, 1, "TX  ");
  hud_text(cr, hud->regular, 10.667, x, y, 0xb8bec6, 1, 1, tx);
}

static void hud_ticker(Hud *hud, cairo_t *cr, double t) {
  double offset = floor(fmod(t * .045, hud->ticker_period));
  cairo_set_source_surface(cr, hud->ticker, HUD_TICKER_X - offset, HUD_TICKER_Y);
  cairo_rectangle(cr, HUD_TICKER_X, HUD_TICKER_Y, HUD_TICKER_W, HUD_TICKER_H);
  cairo_fill(cr);
}

static void hud_ticker_fade(cairo_t *cr) {
  cairo_save(cr);
  /* Soft fade at both ends of the strip. */
  for (int side = 0; side < 2; ++side) {
    double ex = side ? HUD_TICKER_X + HUD_TICKER_W - 40 : HUD_TICKER_X;
    cairo_pattern_t *fade = cairo_pattern_create_linear(ex, 0, ex + 40, 0);
    cairo_pattern_add_color_stop_rgba(fade, 0, 0, 0, 0, side ? 0 : 1);
    cairo_pattern_add_color_stop_rgba(fade, 1, 0, 0, 0, side ? 1 : 0);
    cairo_set_source(cr, fade);
    cairo_rectangle(cr, ex, HUD_TICKER_Y, 40, HUD_TICKER_H);
    cairo_fill(cr);
    cairo_pattern_destroy(fade);
  }
  cairo_restore(cr);
}

static void hud_dot(cairo_t *cr, double t) {
  double pulse = .5 + .5 * cos(t * 2 * HUD_PI / 1200.0);
  hud_rgb(cr, 0xff4050, .25 + .75 * pulse);
  cairo_rectangle(cr, HUD_DOT_X, HUD_DOT_Y, 6, 6); cairo_fill(cr);
  hud_rgb(cr, 0xff4050, .25 * pulse);
  cairo_rectangle(cr, HUD_DOT_X - 2, HUD_DOT_Y - 2, 10, 10); cairo_fill(cr);
}

static void hud_edge(cairo_t *cr, double t, double x, int down) {
  const double top = HUD_EDGE_TOP, span = HUD_EDGE_BOTTOM - HUD_EDGE_TOP, len = 90;
  double u = fmod(t, 3200.0) / 3200.0;
  double head = top + (down ? u : 1 - u) * span;
  double tail = head + (down ? -len : len);
  cairo_pattern_t *beam = cairo_pattern_create_linear(0, tail, 0, head);
  cairo_pattern_add_color_stop_rgba(beam, 0, 1, .25, .31, 0);
  cairo_pattern_add_color_stop_rgba(beam, 1, 1, .25, .31, .95);
  cairo_save(cr);
  cairo_rectangle(cr, x, top, 2, span);  /* enter and leave at the track ends */
  cairo_clip(cr);
  cairo_set_source(cr, beam);
  cairo_rectangle(cr, x, down ? tail : head, 2, len);
  cairo_fill(cr);
  cairo_restore(cr);
  cairo_pattern_destroy(beam);
}

static int hud_hex_key(double t) {
  return (int)(t / 900.0) * 64 + ((int)(t / 220.0) % HUD_HEX_ROWS) * 2 +
         (fmod(t, 440.0) < 300);
}

/* Draw widget `i` at time `t` (artwork coordinates). Every widget stays inside
 * its own region, so restoring that region erases the previous frame. */
static void hud_paint(Hud *hud, int i, cairo_t *cr, double t) {
  switch (i) {
    case 0: hud_core(hud, cr, t); break;
    case 1: hud_hex(hud, cr, t); break;
    case 2: hud_bars(hud, cr, t); break;
    case 3: hud_threat(hud, cr, t); break;
    case 4: hud_power(hud, cr, t); break;
    case 5: hud_wave(hud, cr, t); break;
    case 6: hud_ticker(hud, cr, t); hud_ticker_fade(cr); break;
    case 7: hud_dot(cr, t); break;
    case 8: hud_edge(cr, t, 11, 1); break;
    case 9: hud_edge(cr, t, 1907, 0); break;
    case 10: hud_readouts(hud, cr); break;
    case 11: hud_net(hud, cr); break;
    case 12: hud_subsys(hud, cr, t); break;
    case 13: hud_thermal(hud, cr, t); break;
    case 14: hud_power_text(hud, cr, t); break;
    case HUD_BUTTONS_REGION: hud_buttons(hud, cr, t); break;
  }
}

/* Sample the machine once a second and ease the displayed values toward it,
 * so bars and tiles glide instead of jumping. */
static void hud_update(Hud *hud, double t) {
  double dt = t - hud->last_t;
  if (dt < 0 || dt > 1000) dt = 0;
  hud->last_t = t;
  if (hud->stats_live && t >= hud->stats_next) {
    int first = !hud->stats.have_prev;
    stats_sample(&hud->stats, t);
    hud_net_push(hud, t, hud->stats.rx, hud->stats.tx);
    /* Rates need two samples: take the second one quickly. */
    hud->stats_next = t + (first ? 250 : HUD_STATS_PERIOD);
  }
  if (!hud->stats_live) return;
  const SysStats *s = &hud->stats;
  double k = dt > 0 ? 1 - exp(-dt / 350.0) : 1;
  double rate = (s->rx > 0 ? s->rx : 0) + (s->tx > 0 ? s->tx : 0);
  double net = rate > 0 ? log10(1 + rate) / 7 : 0;  /* ~10 MB/s fills */
  struct { double *view, target; } eased[] = {
    {&hud->cpu, s->cpu}, {&hud->mem, s->mem}, {&hud->swap, s->swap},
    {&hud->disk, s->disk}, {&hud->net, net},
    {&hud->bat_pct, s->bat_pct}, {&hud->bat_watts, s->bat_watts}};
  for (size_t i = 0; i < sizeof(eased) / sizeof(eased[0]); ++i)
    *eased[i].view = eased[i].target < 0 ? -1
                     : *eased[i].view < 0 ? eased[i].target
                     : *eased[i].view + (eased[i].target - *eased[i].view) * k;
  for (int i = 0; i < 16; ++i)
    hud->core[i] = s->core[i] < 0 ? -1
                   : hud->core[i] < 0 ? s->core[i]
                   : hud->core[i] + (s->core[i] - hud->core[i]) * k;
  for (int i = 0; i < STATS_T_COUNT; ++i) {
    double target = s->therm[i];
    hud->therm[i] = target < 0 ? -1 : hud->therm[i] < 0 ? target
                    : hud->therm[i] + (target - hud->therm[i]) * k;
    if (hud->therm[i] > hud->therm_peak[i]) hud->therm_peak[i] = hud->therm[i];
  }
  /* Energy flow: faster with more watts; inward while charging. */
  if (hud->bat_watts > 0 && (s->bat_state == STATS_BAT_CHARGING ||
                             s->bat_state == STATS_BAT_DISCHARGING)) {
    double w = hud->bat_watts > 60 ? 60 : hud->bat_watts;
    double dir = s->bat_state == STATS_BAT_CHARGING ? 1 : -1;
    hud->flow_phase += dir * dt / 1000.0 * (.15 + w / 60 * 1.4);
  }
  hud_subsys_update(hud);
  /* Graph full scale follows the visible peak, easing both ways. */
  double peak = HUD_NET_FLOOR;
  for (int i = 0; i < hud->net_count; ++i) {
    if (t - hud->net_t[i] > HUD_NET_WINDOW + 1000) break;
    if (hud->net_rx[i] > peak) peak = hud->net_rx[i];
    if (hud->net_tx[i] > peak) peak = hud->net_tx[i];
  }
  peak *= 1.15;
  hud->net_scale = hud->net_scale <= 0 ? peak
                   : hud->net_scale + (peak - hud->net_scale) * (dt > 0 ? 1 - exp(-dt / 600.0) : 1);
}

#ifndef HUD_NO_X11
/* Draw the regions that are due and expose only those. `force` repaints
 * everything (first frame, after a resize). */
static void hud_draw(Display *dpy, Window window, Pixmap pixmap, Hud *hud,
                     double t, int force) {
  if (!hud->ready) return;
  hud_update(hud, t);
  /* Button state changes (hover, press, pending, refused) show within ~33 ms. */
  if (hud->power_on && t >= hud->power_next) {
    HudPowerUi ui;
    hud->power_next = t + 33;
    if (hud_power_read(dpy, hud->power_root, hud->power_atom, &ui) &&
        memcmp(&ui, &hud->power, sizeof(ui))) {
      int geometry = ui.x != hud->power.x || ui.y != hud->power.y ||
                     ui.w != hud->power.w || ui.h != hud->power.h ||
                     ui.gap != hud->power.gap || ui.horizontal != hud->power.horizontal;
      if (!geometry) {
        for (int a = 0; a < 2; ++a)
          if ((ui.hover == a) != (hud->power.hover == a)) {
            hud->hover_from[a] = hud_hover_mix(hud, a, t);
            hud->hover_t0[a] = t;
          }
        hud->power = ui;
        hud->region[HUD_BUTTONS_REGION].next = 0;
      }
    }
  }
  int shared = 0;
  for (int i = 0; i < HUD_REGIONS; ++i) {
    HudRegion *g = &hud->region[i];
    if (!g->w) continue;
    int due = force || t >= g->next;
    if (i == 1 && due) {
      int key = hud_hex_key(t);
      due = force || key != hud->hex_key;
      if (due) hud->hex_key = key;
    }
    if (!due) continue;
    g->next = t + g->period;  /* no catch-up bursts after a pause */
    cairo_t *cr = hud_context(hud, g->work);
    cairo_set_operator(cr, CAIRO_OPERATOR_SOURCE);
    cairo_set_source_surface(cr, g->pristine, 0, 0);
    cairo_paint(cr);
    cairo_set_operator(cr, CAIRO_OPERATOR_OVER);
    cairo_translate(cr, -g->ax, -g->ay);  /* widgets use artwork coordinates */
    hud_paint(hud, i, cr, t);
    cairo_destroy(cr);
    cairo_surface_flush(g->work);
    int x = hud->left + g->ax, y = hud->top + g->ay;
    if (g->shared) {
      XShmPutImage(dpy, pixmap, hud->gc, g->ximage, 0, 0, x, y,
                   (unsigned)g->w, (unsigned)g->h, False);
      shared = 1;
    } else {
      XPutImage(dpy, pixmap, hud->gc, g->ximage, 0, 0, x, y,
                (unsigned)g->w, (unsigned)g->h);
    }
    XClearArea(dpy, window, x, y, (unsigned)g->w, (unsigned)g->h, False);
    if (i == HUD_BUTTONS_REGION && !hud->power_shown) {
      /* Tell the locker the controls are visible; clicks count from now. */
      long one = 1;
      XChangeProperty(dpy, hud->power_root, hud->power_shown_atom, XA_CARDINAL, 32,
                      PropModeReplace, (unsigned char *)&one, 1);
      hud->power_shown = 1;
    }
  }
  /* Shared buffers are rewritten next frame: wait until the server has
   * copied them (one round trip, only when something was sent). */
  if (shared) XSync(dpy, False);
}
#endif  /* HUD_NO_X11 */
#endif
